test('throws on negative or too big ID length', () => {
  throws(() => {
    nanoid(2147483648)
  }, /Wrong ID size|Invalid typed array length/)
  throws(() => {
    nanoid(-10)
  }, /Wrong ID size|Invalid typed array length/)
  let a = nanoid()
  let b = nanoid()
  notEqual(a, b)
})

test(`generates large IDs`, () => {
  try {
    nanoid(1000)
  } catch {}
  try {
    nanoid(500)
  } catch {}
  let id = nanoid(100)
  equal(id.length, 100)
  for (let char of id) {
    match(urlAlphabet, new RegExp(char, 'g'))
  }
})
